class Solution {
  public int numDecodings(String s) {
    if (s.isEmpty() || s.charAt(0) == '0') {
      return 0;
    }
    int pre = 1, curr = 1;
    for (int i = 1; i < s.length(); i++) {
      int tmp = curr;
      if (s.charAt(i) == '0') {
        if (s.charAt(i - 1) == '1' || s.charAt(i - 1) == '2') {
          curr = pre;
        } else {
          return 0;
        }
      } else if (s.charAt(i - 1) == '1'
          || (s.charAt(i - 1) == '2' && s.charAt(i) >= '1' && s.charAt(i) <= '6')) {
        curr = curr + pre;
      }
      pre = tmp;
    }
    return curr;
  }
}

class Solution:
    def numDecodings(self, s: str) -> int:
        if not s or s[0] == "0":
            return 0
        pre, cur = 1, 1
        for i in range(1, len(s)):
            tmp = cur
            if s[i] == "0":
                if s[i - 1] in "12":
                    cur = pre
                else:
                    return 0
            elif s[i - 1] == "1" or (s[i - 1] == "2" and "1" <= s[i] <= "6"):
                cur = cur + pre
            pre = tmp
        return cur

